-- ---------------------------------------------------------------------

CREATE TYPE "public"."push_platform" AS ENUM('ios', 'android', 'web');--> statement-breakpoint
CREATE TYPE "public"."reservation_status" AS ENUM('confirmed', 'waitlist', 'cancelled', 'no_show');--> statement-breakpoint
CREATE TYPE "public"."user_role" AS ENUM('member', 'coach', 'admin');--> statement-breakpoint

