CREATE INDEX "idempotency_keys_expires_at_idx" ON "idempotency_keys" USING btree ("expires_at");--> statement-breakpoint
CREATE UNIQUE INDEX "push_tokens_token_unique" ON "push_tokens" USING btree ("token");--> statement-breakpoint

-- ---------------------------------------------------------------------
-- 6. Column type upgrades (post-table, post-index)
--
-- `users.email` is declared as `text` in the Drizzle schema because
-- `drizzle-orm/pg-core` has no first-class `citext` column builder.
-- Converting the column here — *after* the unique index is built — is
-- safe: PostgreSQL rebuilds the index automatically as part of the
-- ALTER, and `citext` is a drop-in btree-compatible type. The result is
-- that `UNIQUE(email)` becomes case-insensitive, which matches the
-- Auth_Service normalisation step (Requirement 1.1).
-- ---------------------------------------------------------------------

ALTER TABLE "users" ALTER COLUMN "email" TYPE citext USING ("email"::citext);--> statement-breakpoint

-- ---------------------------------------------------------------------
-- 7. audit_log immutability trigger
--
-- Requirement 22.2: "THE RLS_Policies SHALL deny UPDATE and DELETE on
-- the Audit_Log for every role, including admin; the Audit_Log SHALL be
-- completely immutable and append-only."
--
-- A trigger gives us a database-enforced guarantee that is independent
-- of the RLS layer: even a superuser role (which would ordinarily
-- bypass RLS) is stopped. RLS policies in the next migration add a
-- second line of defence for application roles.
-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION audit_log_immutable() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'audit_log is append-only';
END;
$$ LANGUAGE plpgsql;
--> statement-breakpoint
DROP TRIGGER IF EXISTS audit_log_forbid_update ON "audit_log";--> statement-breakpoint
CREATE TRIGGER audit_log_forbid_update
    BEFORE UPDATE ON "audit_log"
    FOR EACH ROW
    EXECUTE FUNCTION audit_log_immutable();
--> statement-breakpoint
DROP TRIGGER IF EXISTS audit_log_forbid_delete ON "audit_log";--> statement-breakpoint
CREATE TRIGGER audit_log_forbid_delete
    BEFORE DELETE ON "audit_log"
    FOR EACH ROW
    EXECUTE FUNCTION audit_log_immutable();
